// Reuse the exact repository contract assertions against the comparison-only provider.
// Test module substitution only: no production modules or source files are changed.
import './fucq309-local-deps.mjs';
import { registerHooks } from 'node:module';
registerHooks({ load(url, context, nextLoad) {
  const result = nextLoad(url, context);
  if (!url.endsWith('/test/gcsp-repository-contract.test.js')) return result;
  const source = result.source.toString();
  const original = "import { createMemoryRepository, createMemoryStore } from '../gcsp/repository/memory.js';";
  if (source.split(original).length !== 2) throw new Error('Private contract import anchor changed');
  return { ...result, source: source.replace(original,
    "import { createComparisonRepository as createMemoryRepository, createComparisonStore as createMemoryStore } from '../gcsp/comparison/private-repository.js';") };
} });
